// src/plugins/many-ai/geminiVision.js
// Describes an image via the Gemini API — used as an alternative "eyes" for
// the bot: Gemini only produces a text description, which is then dropped
// into history like a [FILE RECEIVED] note; the actual reply is still
// generated by Mistral (resolveReply), same as every other message.
// Fully optional — see AI_GEMINI_VISION_ENABLED in index.js. Disabled by
// default so nothing changes for anyone who hasn't set a GEMINI_API_KEY.
import { withKeyFailover } from "./apiKeys.js";

async function callGeminiDescribe(base64, mimetype, apiKey, model, prompt) {
  let res;
  try {
    res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: [{
          parts: [
            { text: prompt },
            { inline_data: { mime_type: mimetype, data: base64 } },
          ],
        }],
      }),
    });
  } catch (netErr) {
    const e = new Error(`network error: ${netErr.message}`);
    e.isTransient = true;
    throw e;
  }

  if (!res.ok) {
    const body = await res.text();
    if (res.status === 429) {
      const e = new Error("rate_limit");
      e.isRateLimit = true;
      throw e;
    }
    if (res.status === 401 || res.status === 403) {
      const e = new Error(`key rejected (${res.status})`);
      e.isInvalidKey = true;
      throw e;
    }
    if (res.status >= 500) {
      const e = new Error(`Gemini API error ${res.status}`);
      e.isTransient = true;
      throw e;
    }
    throw new Error(`Gemini API error ${res.status}: ${body}`);
  }

  const data = await res.json();
  const parts = data.candidates?.[0]?.content?.parts || [];
  return parts.map(p => p.text || "").join("").trim();
}

/**
 * Core: given raw base64 image data + mimetype, asks Gemini to describe it.
 * Shared by every caller (incoming WhatsApp media, sandbox files, ...).
 * Returns null on any failure — best-effort, never throws to the caller.
 */
export async function describeImageBase64WithGemini(base64, mimetype, ctx, keys, model, userPrompt) {
  try {
    const mime = mimetype || "image/jpeg";
    ctx.log.info(`[many-ai:gemini-vision] calling Gemini (model=${model}, mime=${mime}, ~${Math.round(base64.length / 1024)}KB base64)`);

    const prompt = userPrompt || "Descreva detalhadamente o que você vê nesta imagem, de forma objetiva.";
    const result = await withKeyFailover(keys, (key) => callGeminiDescribe(base64, mime, key, model, prompt), ctx.log);
    ctx.log.info(`[many-ai:gemini-vision] raw response (${result?.length || 0} chars): ${result}`);
    return result;
  } catch (err) {
    ctx.log.error(`[many-ai:gemini-vision] error: ${err.message}`);
    return null;
  }
}

/**
 * Downloads the image from `msg` (a message object with .downloadMedia(),
 * same interface used everywhere else in this plugin) and asks Gemini to
 * describe it in plain text. Returns null on any failure — best-effort,
 * same contract as vision.js's analyzeImage, never throws to the caller.
 */
export async function describeImageWithGemini(msg, ctx, keys, model, userPrompt) {
  const media = await msg.downloadMedia().catch(() => null);
  if (!media?.data) {
    ctx.log.warn(`[many-ai:gemini-vision] downloadMedia returned empty`);
    return null;
  }
  return describeImageBase64WithGemini(media.data, media.mimetype, ctx, keys, model, userPrompt);
}

